private static boolean addToPatternToSetMap(final Map<Patterns, ?> map, final Patterns pattern, final Object setElement) {
    if (!map.containsKey(pattern)) {
        ((Map<Patterns, Set>) map).put(pattern, new HashSet<>());
    }
    return ((Set) map.get(pattern)).add(setElement);
}
